#!/usr/bin/env python3
"""One-file Fenwanovel repository repair installer.

Recommended use in GitHub Codespaces:
    python fenwanovel_one_click_update.py --publish

The installer writes the repaired project, removes obsolete conflicting files,
runs validation, creates a repair branch, commits, pushes, and attempts to open
a pull request. It never adds payment secrets.
"""

from __future__ import annotations

import argparse
import base64
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
from datetime import datetime, timezone

PACKAGE = json.loads('{".firebaserc.example":"ewogICJwcm9qZWN0cyI6IHsKICAgICJkZWZhdWx0IjogIllPVVJfRklSRUJBU0VfUFJPSkVDVF9JRCIKICB9Cn0K",".github/workflows/validate.yml":"",".gitignore":"bm9kZV9tb2R1bGVzLwpmdW5jdGlvbnMvbm9kZV9tb2R1bGVzLwouZmlyZWJhc2UvCmZpcmViYXNlLWRlYnVnLmxvZwouZmlyZWJhc2VyYwouZW52Ci5lbnYuKgohLmVudi5leGFtcGxlCi5EU19TdG9yZQo=","404.html":"","CNAME":"ZmVud2Fub3ZlbC5vbmxpbmUK","FIRST_READ_THIS.txt":"","README.md":"","assets/css/styles.css":"","assets/js/api.js":"","assets/js/auth-page.js":"","assets/js/config.js":"","assets/js/firebase-client.js":"","assets/js/reader.js":"","assets/js/store.js":"","assets/js/ui.js":"","books/testimony-the-irony-of-destiny/book.html":"","books/testimony-the-irony-of-destiny/book.json":"","books/testimony-the-irony-of-destiny/chapter-1.html":"","books/testimony-the-irony-of-destiny/chapter-2.html":"","books/testimony-the-irony-of-destiny/chapter-3.html":"","books/testimony-the-irony-of-destiny/chapter-4.html":"","covers/testimony-the-irony-of-destiny.jpg":"","firebase.json":"","firestore.rules":"","functions/index.js":"","functions/package.json":"","index.html":"","login.html":"","register.html":"","scripts/check_project.py":"","store.html":""}')
OBSOLETE_PATHS = [
    "Script.js",
    "firebase.js",
    "style.css",
]


def run(command: list[str], *, check: bool = True, capture: bool = False, cwd: Path | None = None) -> subprocess.CompletedProcess[str]:
    print("$", " ".join(command))
    return subprocess.run(
        command,
        check=check,
        text=True,
        capture_output=capture,
        cwd=cwd,
    )


def inside_git_repo(root: Path) -> bool:
    result = subprocess.run(
        ["git", "rev-parse", "--is-inside-work-tree"],
        cwd=root,
        text=True,
        capture_output=True,
    )
    return result.returncode == 0 and result.stdout.strip() == "true"


def check_worktree(root: Path, installer_name: str, force: bool) -> None:
    result = subprocess.run(
        ["git", "status", "--porcelain"],
        cwd=root,
        text=True,
        capture_output=True,
        check=True,
    )
    unexpected = []
    for line in result.stdout.splitlines():
        path = line[3:].strip().strip('"') if len(line) > 3 else ""
        if path and path != installer_name:
            unexpected.append(line)
    if unexpected and not force:
        print("\nSafety stop: the repository already contains unrelated uncommitted changes:")
        print("\n".join(unexpected))
        print("\nCommit or discard those changes, then run the installer again.")
        print("Use --force only when you intentionally want to include them.")
        raise SystemExit(2)


def write_package(root: Path) -> None:
    print("\nWriting repaired Fenwanovel project...")
    for rel, encoded in PACKAGE.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(encoded))
        print("  wrote", rel)

    for rel in OBSOLETE_PATHS:
        target = root / rel
        if target.exists():
            if target.is_dir():
                shutil.rmtree(target)
            else:
                target.unlink()
            print("  removed obsolete", rel)


def validate(root: Path) -> None:
    checker = root / "scripts" / "check_project.py"
    if not checker.exists():
        raise RuntimeError("Validation script was not written.")
    run([sys.executable, str(checker)], check=True, cwd=root)


def configure_git_identity(root: Path) -> None:
    name = subprocess.run(["git", "config", "user.name"], cwd=root, text=True, capture_output=True)
    email = subprocess.run(["git", "config", "user.email"], cwd=root, text=True, capture_output=True)
    if not name.stdout.strip():
        run(["git", "config", "user.name", os.getenv("GITHUB_USER", "Fenwanovel Publisher")], cwd=root)
    if not email.stdout.strip():
        run(["git", "config", "user.email", "fenwanovel@users.noreply.github.com"], cwd=root)


def publish(root: Path, installer_path: Path) -> None:
    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    branch = f"repair/fenwanovel-professional-baseline-{stamp}"

    run(["git", "switch", "-c", branch], cwd=root)

    try:
        installer_path.unlink()
        print("Removed installer before commit:", installer_path.name)
    except FileNotFoundError:
        pass

    configure_git_identity(root)
    run(["git", "add", "-A"], cwd=root)

    staged = subprocess.run(
        ["git", "diff", "--cached", "--quiet"],
        cwd=root,
    )
    if staged.returncode == 0:
        print("No repository changes were detected after installation.")
        return

    run([
        "git", "commit", "-m",
        "Replace conflicting prototype with repaired Fenwanovel baseline",
    ], cwd=root)
    run(["git", "push", "-u", "origin", branch], cwd=root)

    pr_body = (
        "This update removes the conflicting legacy scripts, installs the repaired "
        "responsive reader and catalogue, keeps payments disabled until the secure "
        "backend is configured, and adds automated validation."
    )

    gh = shutil.which("gh")
    if gh:
        auth = subprocess.run([gh, "auth", "status"], cwd=root, text=True, capture_output=True)
        if auth.returncode == 0:
            result = subprocess.run(
                [
                    gh, "pr", "create",
                    "--base", "main",
                    "--head", branch,
                    "--title", "Install repaired Fenwanovel professional baseline",
                    "--body", pr_body,
                ],
                cwd=root,
                text=True,
                capture_output=True,
            )
            if result.returncode == 0:
                print("\nPull request created:")
                print(result.stdout.strip())
                return
            print("\nThe branch was pushed, but automatic pull-request creation failed:")
            print(result.stderr.strip())

    print("\nThe repair branch was pushed successfully.")
    print("Open the repository on GitHub, select 'Compare & pull request', then merge it into main.")


def main() -> None:
    parser = argparse.ArgumentParser(description="Install the repaired Fenwanovel repository package.")
    parser.add_argument(
        "--publish",
        action="store_true",
        help="Create a repair branch, commit, push, and attempt to open a pull request.",
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Include unrelated uncommitted changes. Use only when intentional.",
    )
    args = parser.parse_args()

    root = Path.cwd().resolve()
    installer_path = Path(__file__).resolve()
    git_repo = inside_git_repo(root)

    if args.publish and not git_repo:
        print("Run this installer from the root of the cloned GitHub repository or Codespace.")
        raise SystemExit(2)

    if git_repo:
        check_worktree(root, installer_path.name, args.force)

    write_package(root)
    validate(root)

    print("\nFenwanovel project files were installed and validated successfully.")

    if args.publish:
        publish(root, installer_path)
    else:
        print("Run again with --publish to create and push a safe repair branch.")


if __name__ == "__main__":
    main()
